1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
13	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
14	
15	import java.util.Collection;
16	import java.util.List;
17	
18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public interface OwnerMapper {
23	
24	    @Mapping(target = "displayName", source = "owner", qualifiedByName = "formatDisplayName")
25	    @Mapping(target = "initials", source = "owner", qualifiedByName = "formatInitials")
26	    @Mapping(target = "membershipNumber", source = "owner", qualifiedByName = "formatMembershipNumber")
27	    @Mapping(target = "membershipLevel", source = "owner", qualifiedByName = "formatMembershipLevel")
28	    @Mapping(target = "locality", source = "owner", qualifiedByName = "formatLocality")
29	    @Mapping(target = "contactPreference", source = "owner", qualifiedByName = "formatContactPreference")
30	    @Mapping(target = "bulkSignupWarning", ignore = true)
31	    OwnerDto toOwnerDto(Owner owner);
32	
33	    /** Fixed city-to-region table used to derive an owner's {@code locality}. */
34	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
35	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
36	
37	    /**
38	     * Derives an owner's preferred contact channel for the read-only {@code contactPreference}
39	     * field: {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
40	     */
41	    @Named("formatContactPreference")
42	    default String formatContactPreference(Owner owner) {
43	        if (owner == null) {
44	            return null;
45	        }
46	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
47	        return hasEmail ? "EMAIL" : "PHONE";
48	    }
49	
50	    /**
51	     * Derives an owner's {@code locality} from its city using the fixed city-to-region table
52	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD), returning the canonical region string
53	     * or {@code 'UNKNOWN'} when the city is not in the table.
54	     */
55	    @Named("formatLocality")
56	    default String formatLocality(Owner owner) {
57	        if (owner == null) {
58	            return null;
59	        }
60	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
61	    }
62	
63	    /**
64	     * Determines an owner's numeric membership level for the read-only {@code membershipLevel}
65	     * field, assigned at creation and ranging from 1 to 3: it starts at 1, gains 1 when an email
66	     * address is present, gains 1 when the owner had no namesakes at creation (namesakeCount is 0),
67	     * and is capped at 3. Level 4 is reserved for tenure.
68	     */
69	    @Named("formatMembershipLevel")
70	    default Integer formatMembershipLevel(Owner owner) {
71	        if (owner == null) {
72	            return null;
73	        }
74	        int level = 1;
75	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
76	        if (hasEmail) {
77	            level++;
78	        }
79	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
80	        if (noNamesakes) {
81	            level++;
82	        }
83	        return Math.min(level, 3);
84	    }
85	
86	    /**
87	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the last
88	     * two digits of the registrationDate year (e.g. {@code 'SYD-SMI-0007-M26'}), for the read-only
89	     * {@code membershipNumber} field. Null when the customer code or registration date is absent.
90	     */
91	    @Named("formatMembershipNumber")
92	    default String formatMembershipNumber(Owner owner) {
93	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
94	            return null;
95	        }
96	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
97	    }
98	
99	    /**
100	     * Formats an owner's stored names as {@code 'LastName, FirstName'} for the read-only
101	     * {@code displayName} field.
102	     */
103	    @Named("formatDisplayName")
104	    default String formatDisplayName(Owner owner) {
105	        return owner == null ? null : owner.getLastName() + ", " + owner.getFirstName();
106	    }
107	
108	    /**
109	     * Formats an owner's initials as the upper-cased first letters of firstName and
110	     * lastName, dot-separated with a trailing dot (e.g. {@code 'J.S.'}), for the
111	     * read-only {@code initials} field.
112	     */
113	    @Named("formatInitials")
114	    default String formatInitials(Owner owner) {
115	        return owner == null ? null
116	            : Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
117	                + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
118	    }
119	
120	    Owner toOwner(OwnerDto ownerDto);
121	
122	    @Mapping(target = "id", ignore = true)
123	    @Mapping(target = "pets", ignore = true)
124	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
125	    @Mapping(target = "address", source = "address", qualifiedByName = "normalizeAddress")
126	    Owner toOwner(OwnerFieldsDto ownerDto);
127	
128	    /**
129	     * Normalizes a postal address for persistence: whitespace is trimmed and collapsed, the
130	     * text is upper-cased and common street-type abbreviations are expanded (e.g.
131	     * {@code '  12  main  st '} becomes {@code '12 MAIN STREET'}). The required-field rule is
132	     * enforced separately; an address blank after normalization is rejected.
133	     */
134	    @Named("normalizeAddress")
135	    default String normalizeAddress(String address) {
136	        return AddressNormalizer.normalize(address);
137	    }
138	
139	    /**
140	     * Normalizes a telephone number for persistence into canonical E.164 form (e.g.
141	     * {@code '0412 345 678'} becomes {@code '+61412345678'}). The formability rule is
142	     * enforced separately by {@code TelephoneValidation}.
143	     */
144	    @Named("normalizeTelephone")
145	    default String normalizeTelephone(String telephone) {
146	        return TelephoneNormalizer.toE164(telephone);
147	    }
148	
149	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
150	
151	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
152	
153	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
154	        OwnerPageDto ownerPageDto = new OwnerPageDto();
155	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
156	        ownerPageDto.setPage(ownerPage.getNumber());
157	        ownerPageDto.setSize(ownerPage.getSize());
158	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
159	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
160	        return ownerPageDto;
161	    }
162	}
